INSERT INTO `carrera` (`id_carrera`, `nombre`, `duracion`, `descripcion`, `imagen`, `tipo`, `rank`, `nivel`, `estado`) VALUES
(21, 'Licenciatura en Sistemas Computacionales ', 30, 'La Licenciatura en Ingeniería en Sistemas Computacionales tiene como objetivo formar profesionales con conocimientos y habilidades en la administración y el diseño de proyectos de desarrollo de software y hardware, sistemas de información y aplicaciones automatizadas', 'data:image/;base64,', 2, 84, NULL, 1);
INSERT INTO `carrera` (`id_carrera`, `nombre`, `duracion`, `descripcion`, `imagen`, `tipo`, `rank`, `nivel`, `estado`) VALUES
(22, 'Licenciatura en Ciencias de la Educacion', 18, 'La Licenciatura en Educación es una carrera universitaria que prepara a profesionales en el arte de la enseñanza, dotándolos de técnicas y herramientas para transmitir conocimientos y habilidades de manera efectiva a los estudiantes. Su objetivo principal es capacitar a los profesionales de la Licen', 'data:image/;base64, ', 2, 1, NULL, 1),
(23, 'Lic. en Gestión y Administración Pública', 30, NULL, NULL, 2, 3, NULL, 1);
INSERT INTO `carrera` (`id_carrera`, `nombre`, `duracion`, `descripcion`, `imagen`, `tipo`, `rank`, `nivel`, `estado`) VALUES
(24, 'Curso de Computación', 6, 'Curso de Computación', 'data:image/;base64, ', 0, 4, NULL, 1),
(25, 'Utzin', 1, 'Compendio de archivos', 'data:image/;base64,', 2, 12, 4, 1),
(26, 'Secundaria 286', 6, 'Secundaria por acuerdo 286 de la SEP', 'data:image/;base64,', 1, 13, 2, 1),
(27, 'Ing. Industrial', 30, 'La ingeniería industrial se enfoca en optimizar los procesos y sistemas de una organización para aumentar la eficiencia y la productividad.', NULL, 2, 52, NULL, 1);
