INSERT INTO `publicidad_publicidades` (`id_publicidad`, `nombre`, `contenido`, `imagen`, `prioridad`, `n_grupos`, `lugar`, `estado`, `id_usuario`) VALUES
(2, 'Prepa Alfredo', '‼️⚠️PREPA EN UN EXAMEN⚠️‼️\r\n\r\nHola vecin@, busco personas interesadas en concluir su prepa de forma rápida, en un solo examen, contáctame si cumples estos requisitos:\r\n- Mayor de edad\r\n- Estudios previos no concluidos o con muchos conocimientos.\r\n\r\nLa aplicación es SIN COSTO, y solo se paga el certificado si se acredita el examen.\r\n\r\nhttps://udimex.net/chat/  ', 'Estudia tu PREPA !!.png', 2, 0, 0, 1, NULL),
(4, 'Asistente Administrativo', '🌟 ¡Hola vecino, conoces a alguien que quiera estudiar para ASISTENTE ADMINISTRATIV@! 🎓\r\n\r\n¿Tienes secundaria concluida?¿Buscas una carrera dinámica y con amplias oportunidades laborales? ¡Entonces nuestra carrera de Asistente Administrativ@ es perfecta para ti!\r\n\r\nEn solo 16 meses, adquirirás todas las habilidades y conocimientos necesarios para destacar en el mundo empresarial. Nuestro programa te proporcionará:\r\n\r\n✅ Fundamentos de Administración y Organización\r\n✅ Herramientas de Oficina y Tecnología\r\n✅ Organización de Eventos y Gestión de Recursos\r\n✅ Prácticas Profesionales en Empresas de Prestigio\r\n\r\nInformes: wa.me/7226352407', 'asistente.jpg', 3, 30, 0, 0, 513),
(5, 'Prepa a tu ritmo', '🏫 Hola Vecino, ¿Te has preguntado alguna vez si podrías terminar la PREPARATORIA a tu propio ritmo, desde la comodidad de tu hogar y con una duración que se adapte a tus actividades? ¡La respuesta es sí!\r\n\r\n📚 En nuestra plataforma de estudios en línea, te ofrecemos la oportunidad de completar tus estudios de preparatoria en un período flexible de 2 a 12 meses. ¡Sí, lo escuchaste bien! Puedes diseñar tu propio camino educativo, ajustándolo a tus horarios y responsabilidades diarias.\r\n\r\n✅Horario flexible\r\n✅Avanza a tu propio ritmo\r\n✅Apoyo personalizado\r\n✅Costo desde $500 al mes\r\n\r\nInformes: wa.me/7226352407', 'ritmo.jpg', 2, 20, 1, 0, NULL),
(6, 'Prepa Samael', '¡Hola vecino! 📚🎓 termina tu preparatoria en 6 meses con nosotros, manda la palabra UDIMEX a este número y con gusto te daremos una oferta especial. wa.me/5665692220', '471875757_8877945268953063_643057538817611685_n.jpg', 3, 0, 0, 1, 513),
(13, 'Examen prepa', '¡Tu Preparatoria, con un solo examen! 📝🎓\r\n\r\n¿Quieres terminar la Preparatoria pero no tienes tiempo para clases largas? ¡No te preocupes! Ahora puedes hacerlo con solo un examen y estudiar a tu propio ritmo desde casa. 🏠\r\n\r\n✅ Horarios que se adaptan a ti\r\n✅ Guías y apoyo personalizado\r\n✅ Solo necesitas un examen final\r\n✅ Desde $500 al mes\r\n\r\n¡No lo pienses más! Escríbenos para más detalles 📲 wa.me/7226352407', 'web.png', 1, 20, 1, 0, NULL),
(15, 'PREPA ITZEL', 'Hola vecin@s, concluye tu PREPA, en tan solo 6 meses, para más informes inbox.\r\nwa.me/5665692220 📍 Cupos limitados.', 'im.png', 1, 10, 0, 1, NULL),
(17, 'Lic. Publicidad itzel', '¿Tienes experiencia dando clases?\r\n¿Te gustaría TITULARTE en la Lic. Ciencias de la Educación?\r\nwa.me/5665692220', 'escuela3.jpg', 1, 10, 0, 1, NULL),
(18, 'Ingles y Computación', 'Te gustaría aprender Ingles y Computación?para más información  wa.me/5665692220 📍 Cupos limitados.', 'Curso computacion.png', 2, 0, 1, 1, 513),
(19, 'Computacion e Ingles', 'Te gustaria prender Ingles y Computacion?para más informacion  wa.me/5665692220 📍 Cupos limitados.', 'Curso computacion.png', 1, 0, 0, 0, NULL),
(20, 'Computación e Ingles ', 'Vecin@s les gustaria aprender Computación e Ingles?\r\npara más información wa.me/5665692220 📍 Cupos limitados.', 'Curso computacion.png', 1, 0, 0, 0, NULL),
(22, 'ingles jovani', 'Amigo, ¿tienes entre 6 y 17 años?\r\n¿Quieres aprender ingles y computación?\r\nCon gusto te doy informes 😃\r\n​\r\n', 'escuela publicidad.jpg', 1, 0, 1, 1, NULL),
